schema_ddl:
CREATE TABLE studenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    data_nascita DATE NOT NULL,
    email TEXT NOT NULL UNIQUE,
    codice_fiscale TEXT NOT NULL UNIQUE
);

CREATE TABLE academic_records (
    studente_id INT PRIMARY KEY REFERENCES studenti(id),
    media_voti NUMERIC(3,2) CHECK (media_voti BETWEEN 0 AND 30),
    crediti_totali INT CHECK (crediti_totali >= 0),
    data_aggiornamento TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE academic_records ADD CONSTRAINT unique_studente_id UNIQUE (studente_id);
